-- Admin Catalog — the Wonderlands product catalog inside the admin dashboard
-- (/admin -> Catalog), per the founder's directive: the catalog lives in the
-- admin dashboard, not only in Meta Commerce Manager.
--
-- Seeded with the full 114-product pack posted to Facebook Marketplace in
-- October 2026; every row carries its Marketplace outcome
-- (marketplace_status: 'live' | 'flagged'). The admin Catalog section reads
-- this table and can export it back out as a Meta Commerce Manager data feed
-- (CSV) for the Page Shop catalog "Wonderlands World Products".
--
-- INDEPENDENT of the unified-lead migrations (20261020093000 phase 1,
-- 20261021090000 phase 2, 20261022090000 phase 3): this is a brand-new table
-- with no dependencies, so it can be run in the Supabase SQL editor at any
-- time, in any order relative to them.

create table if not exists public.admin_catalog_products (
  id uuid primary key default gen_random_uuid(),
  sku text not null unique,
  name text not null,
  category text not null check (category in ('Pool', 'Spa', 'Tanning Ledge', 'Sauna', 'Gate', 'Cover')),
  brand text,
  dimensions text,
  depth text,
  price_cents integer not null,
  image_url text,
  description text,
  website_link text not null default 'https://www.wonderlandsworld.com/flip',
  marketplace_status text not null default 'live' check (marketplace_status in ('live', 'flagged', 'review')),
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.admin_catalog_products enable row level security;

-- Admin-only, mirroring the repo's admin-table pattern
-- (e.g. installer_licenses / florida_locations: FOR ALL USING is_main_admin()).
drop policy if exists "Admins can manage catalog products" on public.admin_catalog_products;
create policy "Admins can manage catalog products" on public.admin_catalog_products
  for all
  using (public.is_main_admin())
  with check (public.is_main_admin());

drop trigger if exists update_admin_catalog_products_updated_at on public.admin_catalog_products;
create trigger update_admin_catalog_products_updated_at
  before update on public.admin_catalog_products
  for each row execute function public.update_updated_at_column();

-- Seed: 114 products. Prices are the website prices as posted to Marketplace.
-- marketplace_status 'flagged' = Facebook's "looks like a duplicate" hold from
-- the October 2026 posting waves (26 listings, left in place by founder call).
on conflict (sku) do nothing;
